css:
/* ============================================================
   Puff · 即时对话主题（蓝白渐变）
   ============================================================ */

.chat-thread {
  --dress-chat-bg-overlay: transparent;
}

/* ===== 顶栏胶囊 —— 白蓝渐变 ===== */
.chat-thread-pill {
  background: linear-gradient(90deg, #ffffff 0%, #eef6ff 45%, #cfe4ff 100%);
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-radius: 999px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  color: var(--ink);
}
.chat-thread-center h2 {
  color: var(--black);
  font-size: 15px;
  font-weight: 500;
}
.chat-thread-pill .chat-back,
.chat-thread-head-more,
.chat-thread-head-xinsheng {
  color: var(--ink);
  background: transparent;
}
.chat-thread-pill .chat-back {
  color: transparent !important;
  text-shadow: none !important;
  font-size: 0 !important;
  line-height: 0 !important;
  width: 26px !important;
  height: 26px !important;
  position: relative;
  background-color: transparent !important;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23000000'><circle cx='7' cy='8.5' r='2.2'/><circle cx='12' cy='6.5' r='2.2'/><circle cx='17' cy='8.5' r='2.2'/><path d='M12 12c-3.6 0-6.5 2.7-6.5 5.6 0 1.6 1.2 2.4 2.6 2.4 1.3 0 2.1-.6 3.9-.6s2.6.6 3.9.6c1.4 0 2.6-.8 2.6-2.4C18.5 14.7 15.6 12 12 12z'/></svg>") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: 20px 20px !important;
}
.chat-thread-pill .chat-back::before,
.chat-thread-pill .chat-back::after {
  content: none !important;
  display: none !important;
}
.chat-thread-pill .chat-back > * {
  display: none !important;
}
html[data-theme="dark"] .chat-thread-pill {
  background: rgba(42, 42, 42, 0.92);
  border-color: rgba(255, 255, 255, 0.08);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.35);
  color: #f0f0f0;
}
html[data-theme="dark"] .chat-thread-center h2 { color: #f0f0f0; }
html[data-theme="dark"] .chat-thread-pill .chat-back,
html[data-theme="dark"] .chat-thread-head-more,
html[data-theme="dark"] .chat-thread-head-xinsheng {
  color: #f0f0f0;
}
html[data-theme="dark"] .chat-thread-pill .chat-back {
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23f0f0f0'><circle cx='7' cy='8.5' r='2.2'/><circle cx='12' cy='6.5' r='2.2'/><circle cx='17' cy='8.5' r='2.2'/><path d='M12 12c-3.6 0-6.5 2.7-6.5 5.6 0 1.6 1.2 2.4 2.6 2.4 1.3 0 2.1-.6 3.9-.6s2.6.6 3.9.6c1.4 0 2.6-.8 2.6-2.4C18.5 14.7 15.6 12 12 12z'/></svg>") !important;
}

/* ===== 昵称 / 时间 ===== */
.chat-msg-name {
  font-size: 11px;
  opacity: 0.72;
}
.chat-msg-timestamp,
.chat-thread-notice {
  color: var(--soft);
}

/* ===== 对方气泡 —— 蓝白渐变 ===== */
.chat-msg.is-them .chat-bubble {
  background: linear-gradient(135deg, #cfe4ff 0%, #eef6ff 45%, #ffffff 100%);
  color: var(--ink);
  border: none;
  border-radius: 12px;
}
/* ===== 我方气泡 —— 反向白蓝渐变 ===== */
.chat-msg.is-me .chat-bubble {
  background: linear-gradient(135deg, #ffffff 0%, #eef6ff 45%, #cfe4ff 100%);
  color: var(--ink);
  border: none;
  border-radius: 12px;
}
.chat-bubble-primary {
  line-height: 1.55;
}
html[data-theme="dark"] .chat-msg.is-them .chat-bubble {
  background: #2e2e2e;
  color: #efefef;
}
html[data-theme="dark"] .chat-msg.is-me .chat-bubble {
  background: #4a4a4a;
  color: #ececec;
}

/* ===== 只给普通聊天气泡加颜文字 ===== */
.chat-msg.is-them .chat-bubble,
.chat-msg.is-me .chat-bubble {
  position: relative;
  overflow: visible;
}
.chat-msg.is-them .chat-bubble::after,
.chat-msg.is-me .chat-bubble::after {
  content: "ꉂ(ˊᗜˋ*)";
  position: absolute;
  top: -16px;
  right: 8px;
  font-size: 13px;
  line-height: 1;
  color: var(--ink);
  opacity: 0.65;
  pointer-events: none;
  user-select: none;
  white-space: nowrap;
}
.chat-msg.is-them .chat-bubble:has(.puff-transfer)::after,
.chat-msg.is-me .chat-bubble:has(.puff-transfer)::after,
.chat-msg.is-them .chat-bubble:has(.puff-voice-pill)::after,
.chat-msg.is-me .chat-bubble:has(.puff-voice-pill)::after,
.chat-msg.is-them .chat-bubble:has(.chat-qq-quote)::after,
.chat-msg.is-me .chat-bubble:has(.chat-qq-quote)::after {
  content: none !important;
}
html[data-theme="dark"] .chat-msg.is-them .chat-bubble::after,
html[data-theme="dark"] .chat-msg.is-me .chat-bubble::after {
  color: #f0f0f0;
  opacity: 0.7;
}

/* ===== 引用块 —— 纯浅蓝，不带渐变 ===== */
.chat-qq-quote,
.chat-qq-quote * {
  background-image: none !important;
}
.chat-qq-quote {
  background-color: #d6e8ff !important;
  border: none;
  border-radius: 10px;
  opacity: 1;
  color: var(--ink);
}
.chat-qq-quote-name {
  font-size: 11px;
  opacity: 0.85;
  color: var(--ink);
  background: transparent !important;
}
.chat-qq-quote-text {
  font-size: 12px;
  color: var(--ink);
  background: transparent !important;
}
html[data-theme="dark"] .chat-qq-quote {
  background-color: #35507a !important;
  color: #efefef;
}
html[data-theme="dark"] .chat-qq-quote-name,
html[data-theme="dark"] .chat-qq-quote-text {
  color: #efefef;
}

/* ===== 转账卡片 —— 白蓝渐变 ===== */
.puff-transfer {
  background: linear-gradient(135deg, #ffffff 0%, #eef6ff 45%, #cfe4ff 100%);
  border: none;
  border-radius: 12px;
  color: var(--ink);
}
.puff-transfer-badge {
  background: rgba(255, 255, 255, 0.55);
  color: var(--ink);
}
.puff-transfer-k {
  color: var(--ink);
  opacity: 0.75;
}
html[data-theme="dark"] .puff-transfer {
  background: rgba(44, 44, 44, 0.96);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: #efefef;
}
html[data-theme="dark"] .puff-transfer-badge {
  background: rgba(255, 255, 255, 0.08);
  color: #efefef;
}
html[data-theme="dark"] .puff-transfer-k {
  color: #efefef;
  opacity: 0.75;
}

/* ===== 语音条 —— 白蓝渐变 ===== */
.chat-msg.is-them .puff-voice-pill {
  background: linear-gradient(135deg, #ffffff 0%, #eef6ff 45%, #cfe4ff 100%);
  color: var(--ink);
  border: none;
  border-radius: 999px;
}
.chat-msg.is-me .puff-voice-pill {
  background: linear-gradient(135deg, #cfe4ff 0%, #eef6ff 45%, #ffffff 100%);
  color: var(--ink);
  border: none;
  border-radius: 999px;
}
html[data-theme="dark"] .chat-msg.is-them .puff-voice-pill {
  background: #2e2e2e;
  color: #efefef;
}
html[data-theme="dark"] .chat-msg.is-me .puff-voice-pill {
  background: #4a4a4a;
  color: #ececec;
}

/* ===== 翻译展开 ===== */
.chat-bubble-trans-inline,
.chat-bubble-trans-chip {
  opacity: 0.88;
}
.chat-bubble-trans-chip-label {
  font-size: 10px;
  opacity: 0.65;
}

/* ===== 气泡旁「推演」 ===== */
.chat-thinking-chip {
  background: rgba(0, 0, 0, 0.05);
  color: var(--soft);
  border: none;
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 11px;
  letter-spacing: 0.04em;
}
html[data-theme="dark"] .chat-thinking-chip {
  background: rgba(255, 255, 255, 0.08);
  color: #a8a8a8;
}

/* ===== 输入胶囊 —— 白蓝渐变 ===== */
.chat-compose-bar {
  background: linear-gradient(135deg, #cfe4ff 0%, #eef6ff 45%, #ffffff 100%);
  color: var(--ink);
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-radius: 999px;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.08);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}
.chat-compose-plus {
  color: var(--ink);
  background: linear-gradient(135deg, #ffffff 0%, #eef6ff 60%, #cfe4ff 100%);
  border: none;
  border-radius: 999px;
}
.chat-compose-icon.is-voice,
.chat-compose-icon.is-reply {
  color: var(--ink);
  background: linear-gradient(135deg, #ffffff 0%, #eef6ff 60%, #cfe4ff 100%);
  border: none;
  border-radius: 999px;
}
.chat-compose-icon.is-send.ready {
  background: linear-gradient(135deg, #cfe4ff 0%, #eef6ff 45%, #ffffff 100%);
  color: var(--ink);
  border: none;
  border-radius: 999px;
}
.chat-compose-input {
  color: var(--ink);
}
html[data-theme="dark"] .chat-compose-bar {
  background: rgba(42, 42, 42, 0.92);
  border-color: rgba(255, 255, 255, 0.08);
  box-shadow: 0 10px 32px rgba(0, 0, 0, 0.35);
}
html[data-theme="dark"] .chat-compose-input {
  color: #f0f0f0;
}
html[data-theme="dark"] .chat-compose-plus,
html[data-theme="dark"] .chat-compose-icon.is-voice,
html[data-theme="dark"] .chat-compose-icon.is-reply {
  color: #f0f0f0;
  background: rgba(255, 255, 255, 0.08);
}
html[data-theme="dark"] .chat-compose-icon.is-send.ready {
  background: #4a4a4a;
  color: #ececec;
}
